<?php
if(!defined('SCHOOLOS_INSIGHTS_LIBRARY')){header('Location: index.php?s=intelligence&area=academics');exit;}
function at_schema():array{return [
 "CREATE TABLE IF NOT EXISTS at_curricula(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,authority VARCHAR(20) NOT NULL,version VARCHAR(100) NOT NULL,reference_url VARCHAR(1200) NOT NULL,subjects_json TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS at_class_policies(tenant_id BIGINT UNSIGNED NOT NULL,class_id BIGINT UNSIGNED NOT NULL,curriculum_id BIGINT UNSIGNED NOT NULL,design_id BIGINT UNSIGNED NOT NULL,calendar_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(tenant_id,class_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS at_designs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,level VARCHAR(20) NOT NULL,layout_json TEXT NOT NULL,ca_weight INT NOT NULL,exam_weight INT NOT NULL,promotion_percent INT NOT NULL,grades_json TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS at_observations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,session_name VARCHAR(100) NOT NULL,term_name VARCHAR(70) NOT NULL,skill VARCHAR(100) NOT NULL,rating INT NOT NULL,note VARCHAR(1000) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS at_calendars(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,state_name VARCHAR(40) NOT NULL,year_name VARCHAR(30) NOT NULL,starts_on DATE NOT NULL,ends_on DATE NOT NULL,holidays_json TEXT NOT NULL,inspection_notes TEXT NOT NULL,reference_url VARCHAR(1200) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS at_rooms(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,capacity INT NOT NULL,UNIQUE KEY room_name(tenant_id,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS at_slots(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,weekday INT NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,UNIQUE KEY slot_once(tenant_id,weekday,start_time,end_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS at_unavailable(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,weekday INT NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,reason VARCHAR(300) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS at_plans(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,session_name VARCHAR(100) NOT NULL,baseline_hash CHAR(64) NOT NULL,rows_json MEDIUMTEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED NULL,review_note VARCHAR(1000) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];}
function at_states():array{return explode('|','Abia|Adamawa|Akwa Ibom|Anambra|Bauchi|Bayelsa|Benue|Borno|Cross River|Delta|Ebonyi|Edo|Ekiti|Enugu|FCT|Gombe|Imo|Jigawa|Kaduna|Kano|Katsina|Kebbi|Kogi|Kwara|Lagos|Nasarawa|Niger|Ogun|Ondo|Osun|Oyo|Plateau|Rivers|Sokoto|Taraba|Yobe|Zamfara');}
function at_layout(string $json):array{$v=json_decode($json,true,32,JSON_THROW_ON_ERROR);$allowed=['identity','subjects','attendance','skills','teacher_comment','head_comment','promotion','signatures'];if(!is_array($v)||!array_is_list($v)||!$v||count($v)>8||count(array_unique($v))!==count($v)||array_diff($v,$allowed))throw new RuntimeException('Use unique allowlisted report blocks.');return $v;}
function at_grades(string $json):array{$v=json_decode($json,true,32,JSON_THROW_ON_ERROR);if(!is_array($v)||!array_is_list($v)||!$v||count($v)>12)throw new RuntimeException('Use 1–12 grade bands.');$prior=101;foreach($v as $r){if(!is_array($r)||!isset($r['minimum'],$r['grade'])||!is_numeric($r['minimum'])||(float)$r['minimum']<0||(float)$r['minimum']>100||(float)$r['minimum']>=$prior||!is_string($r['grade'])||mb_strlen($r['grade'])>30)throw new RuntimeException('Use descending numeric minimums and short grade labels.');$prior=(float)$r['minimum'];}if($prior!==0.0)throw new RuntimeException('Last grade minimum must be zero.');return $v;}
function at_baseline(int $tid,string $session):string{$parts=[q('SELECT * FROM ac_timetable WHERE tenant_id=? AND session_name=? ORDER BY id',[$tid,$session])->fetchAll(),q('SELECT a.* FROM ac_allocations a JOIN classes c ON c.id=a.class_id AND c.tenant_id=a.tenant_id AND c.session_name=a.session_name JOIN users u ON u.id=a.teacher_id AND u.tenant_id=a.tenant_id AND u.active=1 AND u.role=\'teacher\' WHERE a.tenant_id=? AND a.session_name=? ORDER BY a.id',[$tid,$session])->fetchAll(),q('SELECT * FROM at_rooms WHERE tenant_id=? ORDER BY id',[$tid])->fetchAll(),q('SELECT * FROM at_slots WHERE tenant_id=? ORDER BY id',[$tid])->fetchAll(),q('SELECT * FROM at_unavailable WHERE tenant_id=? ORDER BY id',[$tid])->fetchAll(),q('SELECT id,class_id FROM students WHERE tenant_id=? ORDER BY id',[$tid])->fetchAll()];return hash('sha256',json_encode($parts,JSON_THROW_ON_ERROR));}
function at_conflict(array $row,array $others):bool{foreach($others as $o)if((int)$o['weekday']===(int)$row['weekday']&&$o['start_time']<$row['end_time']&&$o['end_time']>$row['start_time']&&((int)$o['class_id']===(int)$row['class_id']||(int)$o['teacher_id']===(int)$row['teacher_id']||($o['room']!==null&&$o['room']===$row['room'])))return true;return false;}
function at_validate_row(int $tid,string $session,array $row,array $existing):void{$u=q("SELECT a.* FROM ac_allocations a JOIN users u ON u.id=a.teacher_id AND u.tenant_id=a.tenant_id AND u.active=1 AND u.role='teacher' JOIN classes c ON c.id=a.class_id AND c.tenant_id=a.tenant_id AND c.session_name=a.session_name WHERE a.tenant_id=? AND a.class_id=? AND a.subject_id=? AND a.teacher_id=? AND a.session_name=?",[$tid,$row['class_id'],$row['subject_id'],$row['teacher_id'],$session])->fetch();$room=q('SELECT * FROM at_rooms WHERE tenant_id=? AND name=?',[$tid,$row['room']])->fetch();$slot=q('SELECT id FROM at_slots WHERE tenant_id=? AND weekday=? AND start_time=? AND end_time=?',[$tid,$row['weekday'],$row['start_time'],$row['end_time']])->fetch();if(!$u||!$room||!$slot||(int)$room['capacity']<(int)g('SELECT COUNT(*) FROM students WHERE tenant_id=? AND class_id=?',[$tid,$row['class_id']])||at_conflict($row,$existing)||g('SELECT id FROM at_unavailable WHERE tenant_id=? AND user_id=? AND weekday=? AND start_time<? AND end_time>?',[$tid,$row['teacher_id'],$row['weekday'],$row['end_time'],$row['start_time']]))throw new RuntimeException('Timetable constraint failed: allocation, room capacity, slot, overlap or availability.');}
function at_generate(array $u,string $session,array $requirements):int{ix_need($u,'timetable_manager');if(!$requirements||count($requirements)>40)throw new RuntimeException('Use 1–40 allocation requirements.');$tid=(int)$u['tenant_id'];$baseline=at_baseline($tid,$session);$existing=q('SELECT * FROM ac_timetable WHERE tenant_id=? AND session_name=?',[$tid,$session])->fetchAll();$slots=q('SELECT * FROM at_slots WHERE tenant_id=? ORDER BY weekday,start_time',[$tid])->fetchAll();$rooms=q('SELECT * FROM at_rooms WHERE tenant_id=? ORDER BY capacity,name',[$tid])->fetchAll();$tasks=[];$seen=[];foreach($requirements as $req){if(!is_array($req)||!isset($req['allocation_id'],$req['periods'])||(int)$req['periods']<1||(int)$req['periods']>10||isset($seen[(int)$req['allocation_id']]))throw new RuntimeException('Use unique allocation IDs and 1–10 additional periods.');$seen[(int)$req['allocation_id']]=true;$a=q('SELECT * FROM ac_allocations WHERE tenant_id=? AND id=? AND session_name=?',[$tid,(int)$req['allocation_id'],$session])->fetch();if(!$a)throw new RuntimeException('Allocation unavailable.');for($i=0;$i<(int)$req['periods'];$i++)$tasks[]=$a;}if(count($tasks)>60)throw new RuntimeException('Limit each generation to 60 additional periods.');$chosen=[];$nodes=0;$valid=[];if(count($slots)>100||count($rooms)>50)throw new RuntimeException('Limit this workspace to 100 slots and 50 rooms.');foreach($tasks as $a){if(isset($valid[$a['id']]))continue;$valid[$a['id']]=[];foreach($slots as $slot)foreach($rooms as $room){$r=['class_id'=>(int)$a['class_id'],'subject_id'=>(int)$a['subject_id'],'teacher_id'=>(int)$a['teacher_id'],'weekday'=>(int)$slot['weekday'],'start_time'=>$slot['start_time'],'end_time'=>$slot['end_time'],'room'=>$room['name']];try{at_validate_row($tid,$session,$r,$existing);$valid[$a['id']][]=$r;}catch(Throwable $e){}}}
 $solve=function(int $index)use(&$solve,&$chosen,&$nodes,$tasks,$valid,$existing,$tid,$session):bool{if($index===count($tasks))return true;if(++$nodes>20000)return false;$a=$tasks[$index];$candidates=[];foreach($valid[$a['id']] as $r){if(at_conflict($r,$chosen))continue;$penalty=0;foreach(array_merge($existing,$chosen) as $old)if((int)$old['weekday']===(int)$r['weekday']){$penalty+=(int)$old['class_id']===$r['class_id']?3:0;$penalty+=(int)$old['teacher_id']===$r['teacher_id']?1:0;if((int)$old['subject_id']===$r['subject_id']&&(int)$old['class_id']===$r['class_id'])$penalty+=5;}$candidates[]=[$penalty,$r];}usort($candidates,fn($a,$b)=>$a[0]<=>$b[0]);foreach($candidates as [$score,$r]){$chosen[]=$r;if($solve($index+1))return true;array_pop($chosen);}return false;};if(!$solve(0))throw new RuntimeException('No complete feasible proposal found within the bounded search. Change requirements, rooms, availability or slots; nothing was written.');if(!hash_equals($baseline,at_baseline($tid,$session)))throw new RuntimeException('Timetable inputs changed; regenerate.');q('INSERT INTO at_plans(tenant_id,session_name,baseline_hash,rows_json,created_by) VALUES(?,?,?,?,?)',[$tid,$session,$baseline,json_encode($chosen),$u['id']]);return (int)$GLOBALS['pdo']->lastInsertId();}
function at_lock(int $tid):string{$name='schoolos-time-'.substr(hash('sha256',(string)g('SELECT DATABASE()')),0,12).'-'.$tid;if(!(int)g('SELECT GET_LOCK(?,5)',[$name]))throw new RuntimeException('Another timetable operation is running.');return $name;}
function at_report_data(array $u,int $sid,int $design,string $session,string $term):array{$s=sv_own('students',$u,$sid);if(in_array($u['role'],['parent','student'],true))op_child($u,$sid);elseif($u['role']==='teacher'&&!ix_can($u,'curriculum_manager'))lp_pupil($u,$sid);else ix_need($u,'curriculum_manager');$d=ix_own('at_designs',$u,$design);if($d['status']!=='approved')throw new RuntimeException('Use an approved report design.');$observations=q("SELECT skill,rating,note FROM at_observations WHERE tenant_id=? AND student_id=? AND session_name=? AND term_name=? AND status='approved' ORDER BY skill,id",[$u['tenant_id'],$sid,$session,$term])->fetchAll();$rows=[];if($d['level']!=='nursery'){if(!acPublished((int)$u['tenant_id'],(int)$s['class_id'],$session,$term))throw new RuntimeException('Publish the approved term through existing Academics first.');$weights=q('SELECT subject_id,SUM(CASE WHEN category=\'ca\' THEN weight ELSE 0 END) ca,SUM(CASE WHEN category=\'exam\' THEN weight ELSE 0 END) exam FROM ac_assessments WHERE tenant_id=? AND class_id=? AND session_name=? AND term_name=? GROUP BY subject_id',[$u['tenant_id'],$s['class_id'],$session,$term])->fetchAll();foreach($weights as $w)if(abs((float)$w['ca']-(int)$d['ca_weight'])>0.01||abs((float)$w['exam']-(int)$d['exam_weight'])>0.01)throw new RuntimeException('Assessment weights must match the approved CA/exam design for every subject.');foreach(acTermResults((int)$u['tenant_id'],(int)$s['class_id'],$session,$term,true) as $r)if((int)$r['student_id']===$sid){if(abs((float)$r['possible']-100)>0.01)throw new RuntimeException('Incomplete approved subject components.');$grade='';foreach(json_decode($d['grades_json'],true) as $band)if((float)$r['total']>=(float)$band['minimum']){$grade=$band['grade'];break;}$rows[]=['subject'=>$r['subject_name'],'total'=>round((float)$r['total'],2),'grade'=>$grade];}if(!$rows)throw new RuntimeException('No complete published results for this student.');}$attendance=q('SELECT status,COUNT(*) records FROM attendance WHERE tenant_id=? AND student_id=? GROUP BY status',[$u['tenant_id'],$sid])->fetchAll();return ['student'=>$s,'design'=>$d,'subjects'=>$rows,'skills'=>$observations,'attendance'=>$attendance,'session'=>$session,'term'=>$term];}
function at_print(array $u,int $sid,int $design,string $session,string $term):void{$r=at_report_data($u,$sid,$design,$session,$term);header('Content-Type: text/html; charset=utf-8');header('Cache-Control: private, no-store');echo '<!doctype html><html><meta name="viewport" content="width=device-width,initial-scale=1"><title>School report card</title><style>body{font:15px system-ui;max-width:900px;padding:30px;margin:auto}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd}.block{margin:24px 0}@media print{button{display:none}}</style><h1>'.e(g('SELECT name FROM tenants WHERE id=?',[$u['tenant_id']])).'</h1>';foreach(json_decode($r['design']['layout_json'],true) as $block){echo '<section class="block">';if($block==='identity')echo '<h2>'.e($r['student']['name']).'</h2><p>'.e($r['session'].' · '.$r['term'].' · '.$r['design']['level']).'</p>';elseif($block==='subjects')op_table($r['subjects'],['Subject','Weighted total /100','Grade']);elseif($block==='skills')op_table($r['skills'],['Observed skill','Rating /5','Approved comment']);elseif($block==='attendance'){echo '<p>All recorded attendance (term-date boundaries not inferred):</p>';op_table($r['attendance'],['Status','Recorded days']);}elseif($block==='promotion'){$mean=$r['subjects']?array_sum(array_column($r['subjects'],'total'))/count($r['subjects']):null;echo '<p>Promotion review: '.($mean===null?'Nursery progress requires human review':($mean>=(int)$r['design']['promotion_percent']?'Meets configured score threshold; school approval still required':'Below configured threshold; human review required')).'</p>';}elseif($block==='signatures')echo '<p>Teacher signature: __________________ School approval: __________________</p>';else echo '<p>'.e(str_replace('_',' ',ucfirst($block))).': ______________________________________________</p>';echo '</section>';}echo '<button onclick="window.print()">Print / save PDF</button></html>';exit;}
function at_action(array $u,string $a):string{
 $tid=(int)$u['tenant_id'];$uid=(int)$u['id'];
 if($a==='observation'){$sid=op_id('student_id');if($u['role']==='teacher')lp_pupil($u,$sid);else{ix_need($u,'curriculum_manager');sv_own('students',$u,$sid);}q('INSERT INTO at_observations(tenant_id,student_id,session_name,term_name,skill,rating,note,created_by) VALUES(?,?,?,?,?,?,?,?)',[$tid,$sid,op_text('session_name',100,true),op_text('term_name',70,true),op_text('skill',100,true),sv_qty('rating',5),op_text('note',1000,true),$uid]);return 'Observational assessment saved as draft for independent review.';}
 if(in_array($a,['room','slot','unavailable','generate','review_plan','apply_plan'],true)){
  ix_need($u,'timetable_manager');if($a==='room'){q('INSERT INTO at_rooms(tenant_id,name,capacity) VALUES(?,?,?)',[$tid,op_text('name',100,true),sv_qty('capacity',1000)]);return 'School timetable room registered.';}if($a==='slot'||$a==='unavailable'){$day=sv_qty('weekday',7);$start=op_time(op_text('start_time',5,true));$end=op_time(op_text('end_time',5,true));if($end<=$start)throw new RuntimeException('End must follow start.');if($a==='slot')q('INSERT INTO at_slots(tenant_id,weekday,start_time,end_time) VALUES(?,?,?,?)',[$tid,$day,$start,$end]);else{$teacher=sv_own('users',$u,op_id('user_id'));if($teacher['role']!=='teacher')throw new RuntimeException('Teacher account required.');q('INSERT INTO at_unavailable(tenant_id,user_id,weekday,start_time,end_time,reason) VALUES(?,?,?,?,?,?)',[$tid,$teacher['id'],$day,$start,$end,op_text('reason',300,true)]);}return 'Timetable constraint registered.';}if($a==='generate'){$requirements=json_decode(op_text('requirements',10000,true),true,32,JSON_THROW_ON_ERROR);$id=at_generate($u,op_text('session_name',100,true),$requirements);return 'Feasible timetable proposal #'.$id.' generated; no live periods replaced.';}
  $lock=at_lock($tid);try{return sv_tx(function()use($u,$tid,$uid,$a){$p=ix_own('at_plans',$u,op_id('plan_id'),true);if(!hash_equals($p['baseline_hash'],at_baseline($tid,$p['session_name'])))throw new RuntimeException('Inputs or live timetable changed; regenerate the proposal.');$author=ix_fresh($tid,(int)$p['created_by']);ix_need($author,'timetable_manager');$rows=json_decode($p['rows_json'],true);$existing=q('SELECT * FROM ac_timetable WHERE tenant_id=? AND session_name=?',[$tid,$p['session_name']])->fetchAll();foreach($rows as $r){at_validate_row($tid,$p['session_name'],$r,$existing);$existing[]=$r;}if($a==='review_plan'){if($p['status']!=='draft'||(int)$p['created_by']===$uid)throw new RuntimeException('A different reviewer must approve the draft plan.');q("UPDATE at_plans SET status='approved',approved_by=?,review_note=? WHERE tenant_id=? AND id=?",[$uid,op_text('review_note',1000,true),$tid,$p['id']]);return 'Timetable proposal independently approved.';}if($u['role']!=='school_admin'||$p['status']!=='approved')throw new RuntimeException('School administrator must apply an approved unexecuted proposal.');ix_need(ix_fresh($tid,(int)$p['approved_by']),'timetable_manager');foreach($rows as $r)q('INSERT INTO ac_timetable(tenant_id,class_id,subject_id,teacher_id,weekday,start_time,end_time,room,session_name) VALUES(?,?,?,?,?,?,?,?,?)',[$tid,$r['class_id'],$r['subject_id'],$r['teacher_id'],$r['weekday'],$r['start_time'],$r['end_time'],$r['room'],$p['session_name']]);q("UPDATE at_plans SET status='applied' WHERE tenant_id=? AND id=?",[$tid,$p['id']]);return 'Approved proposal applied once to existing timetable; prior periods retained.';});}finally{q('SELECT RELEASE_LOCK(?)',[$lock]);}
 }
 ix_need($u,'curriculum_manager');
 if($a==='subject'){q('INSERT INTO subjects(tenant_id,name,code) VALUES(?,?,?)',[$tid,op_text('name',150,true),ix_key(op_text('code',30,true),30)]);return 'School-specific subject added to existing subject list.';}
 if($a==='curriculum'){$authority=sv_enum('authority',['NERDC','school']);$ids=array_values(array_unique(array_map('intval',explode(',',op_text('subjects',2000,true)))));if(!$ids||count($ids)>100)throw new RuntimeException('Choose 1–100 school subject IDs.');foreach($ids as $id)ix_own('subjects',$u,$id);q('INSERT INTO at_curricula(tenant_id,name,authority,version,reference_url,subjects_json,created_by) VALUES(?,?,?,?,?,?,?)',[$tid,op_text('name',180,true),$authority,op_text('version',100,true),sv_https(op_text('reference_url',1200,true)),json_encode($ids),$uid]);return 'Versioned curriculum reference submitted for school review; official NERDC content is not inferred.';}
 if($a==='design'){$layout=at_layout(op_text('layout',2000,true));$ca=sv_qty('ca_weight',100,true);$exam=sv_qty('exam_weight',100,true);$level=sv_enum('level',['nursery','primary','secondary']);if($level!=='nursery'&&$ca+$exam!==100)throw new RuntimeException('CA and exam weights must total 100.');$grades=at_grades(op_text('grades',3000,true));q('INSERT INTO at_designs(tenant_id,name,level,layout_json,ca_weight,exam_weight,promotion_percent,grades_json,created_by) VALUES(?,?,?,?,?,?,?,?,?)',[$tid,op_text('name',180,true),$level,json_encode($layout),$ca,$exam,sv_qty('promotion_percent',100,true),json_encode($grades),$uid]);return 'Report-card layout and Nigerian CA/exam conventions saved as an immutable draft.';}
 if($a==='approve_curriculum'||$a==='approve_design'||$a==='approve_observation'){$table=['approve_curriculum'=>'at_curricula','approve_design'=>'at_designs','approve_observation'=>'at_observations'][$a];return sv_tx(function()use($u,$tid,$uid,$table){$r=ix_own($table,$u,op_id('record_id'),true);if($r['status']!=='draft'||(int)$r['created_by']===$uid)throw new RuntimeException('A different authorized reviewer must approve the draft.');q("UPDATE `$table` SET status='approved',approved_by=? WHERE tenant_id=? AND id=?",[$uid,$tid,$r['id']]);return 'School review approved.';});}
 if($a==='calendar'){$start=op_date(op_text('starts_on',10,true));$end=op_date(op_text('ends_on',10,true));if($end<$start)throw new RuntimeException('Invalid calendar period.');$holidays=json_decode(op_text('holidays',10000,true),true,32,JSON_THROW_ON_ERROR);if(!is_array($holidays)||!array_is_list($holidays)||count($holidays)>150)throw new RuntimeException('Use an array of holiday dates.');foreach($holidays as $date)if(op_date((string)$date)<$start||$date>$end)throw new RuntimeException('Holiday falls outside calendar.');$state=op_text('state_name',40,true);if(!in_array($state,at_states(),true))throw new RuntimeException('Choose a Nigerian state or FCT.');q('INSERT INTO at_calendars(tenant_id,name,state_name,year_name,starts_on,ends_on,holidays_json,inspection_notes,reference_url) VALUES(?,?,?,?,?,?,?,?,?)',[$tid,op_text('name',180,true),$state,op_text('year_name',30,true),$start,$end,json_encode($holidays),op_text('inspection_notes',5000,true),sv_https(op_text('reference_url',1200,true))]);return 'School-reviewed state calendar and inspection configuration saved. No statutory dates were assumed.';}
 if($a==='class_policy'){$class=sv_own('classes',$u,op_id('class_id'));$curr=ix_own('at_curricula',$u,op_id('curriculum_id'));$design=ix_own('at_designs',$u,op_id('design_id'));$calendar=ix_own('at_calendars',$u,op_id('calendar_id'));if($curr['status']!=='approved'||$design['status']!=='approved')throw new RuntimeException('Choose approved curriculum and report format.');q('INSERT INTO at_class_policies VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE curriculum_id=VALUES(curriculum_id),design_id=VALUES(design_id),calendar_id=VALUES(calendar_id)',[$tid,$class['id'],$curr['id'],$design['id'],$calendar['id']]);return 'Explicit class curriculum/report/calendar policy bound; existing records unchanged.';}
 throw new RuntimeException('Unsupported academic tool action.');
}
function at_hash(?array $r,array $keys):string{$data=[];foreach($keys as $key)$data[$key]=$r[$key]??null;return hash('sha256',json_encode($data,JSON_THROW_ON_ERROR));}
function at_attendance_hash(?array $r):string{return at_hash($r,['id','status']);}
function at_score_hash(?array $r):string{return at_hash($r,['id','score','status','entered_by','updated_at']);}
function at_snapshot(array $u,int $class,string $day):array{
 if($u['role']!=='teacher'||!ix_setting((int)$u['tenant_id'],'offline_enabled'))throw new RuntimeException('School-approved teacher offline capture required.');lp_scope($u,$class);op_date($day);if($day>date('Y-m-d')||$day<date('Y-m-d',time()-30*86400))throw new RuntimeException('Choose a recorded attendance date within the last 30 days.');$tid=(int)$u['tenant_id'];$students=q('SELECT id,name,student_no FROM students WHERE tenant_id=? AND class_id=? ORDER BY name LIMIT 250',[$tid,$class])->fetchAll();$assessments=q('SELECT a.* FROM ac_assessments a JOIN ac_allocations x ON x.tenant_id=a.tenant_id AND x.class_id=a.class_id AND x.subject_id=a.subject_id AND x.session_name=a.session_name JOIN classes c ON c.id=a.class_id AND c.tenant_id=a.tenant_id AND c.session_name=a.session_name WHERE a.tenant_id=? AND a.class_id=? AND x.teacher_id=? ORDER BY a.id DESC LIMIT 40',[$tid,$class,$u['id']])->fetchAll();$attendance=[];$scores=[];foreach($students as $s){$r=q('SELECT * FROM attendance WHERE tenant_id=? AND student_id=? AND attendance_date=?',[$tid,$s['id'],$day])->fetch()?:null;$attendance[$s['id']]=['status'=>$r['status']??'','base_hash'=>at_attendance_hash($r)];}foreach($assessments as &$a){$a['published']=acPublished($tid,$class,$a['session_name'],$a['term_name']);foreach($students as $s){$r=q('SELECT * FROM ac_scores WHERE tenant_id=? AND assessment_id=? AND student_id=?',[$tid,$a['id'],$s['id']])->fetch()?:null;$scores[$a['id']][$s['id']]=['value'=>$r['score']??'','editable'=>!$a['published']&&(!$r||$r['status']==='draft'),'base_hash'=>at_score_hash($r)];}}unset($a);return ['version'=>1,'tenant_id'=>$tid,'user_id'=>(int)$u['id'],'class_id'=>$class,'day'=>$day,'captured_at'=>date('c'),'expires_at'=>time()+7*86400,'students'=>$students,'assessments'=>$assessments,'attendance'=>$attendance,'scores'=>$scores];
}
function at_sync(array $u,array $payload):array{
 if($u['role']!=='teacher'||!ix_setting((int)$u['tenant_id'],'offline_enabled')||(int)($payload['tenant_id']??0)!==(int)$u['tenant_id']||(int)($payload['user_id']??0)!==(int)$u['id'])throw new RuntimeException('Offline workspace does not belong to the current authorized teacher.');$ops=$payload['operations']??[];if(!is_array($ops)||!array_is_list($ops)||count($ops)>100)throw new RuntimeException('Use at most 100 synchronization operations.');$results=[];$tid=(int)$u['tenant_id'];foreach($ops as $op){$event=is_array($op)?(string)($op['event_key']??''):'';try{ix_key($event,80);$hash=hash('sha256',json_encode($op,JSON_THROW_ON_ERROR));$results[]=sv_tx(function()use($u,$tid,$op,$event,$hash){q('SELECT id FROM users WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$u['id']]);$old=q('SELECT * FROM ix_sync WHERE tenant_id=? AND user_id=? AND event_key=?',[$tid,$u['id'],$event])->fetch();if($old){if(!hash_equals($old['payload_hash'],$hash))throw new RuntimeException('Synchronization key was reused with changed content.');return json_decode($old['result_json'],true);}$kind=$op['kind']??'';$sid=(int)($op['student_id']??0);$base=(string)($op['base_hash']??'');if(!preg_match('/^[a-f0-9]{64}$/D',$base))throw new RuntimeException('Missing base version.');
  if($kind==='attendance'){$s=lp_pupil($u,$sid);q('SELECT id FROM students WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$sid]);$day=op_date((string)($op['day']??''));if($day>date('Y-m-d')||$day<date('Y-m-d',time()-30*86400))throw new RuntimeException('Attendance date is outside the sync window.');$r=q('SELECT * FROM attendance WHERE tenant_id=? AND student_id=? AND attendance_date=? FOR UPDATE',[$tid,$sid,$day])->fetch()?:null;$current=at_attendance_hash($r);$value=(string)($op['value']??'');if(!in_array($value,['present','late','absent','excused'],true))throw new RuntimeException('Invalid attendance state.');if(!hash_equals($base,$current))$result=['event_key'=>$event,'status'=>'conflict','current'=>$r['status']??'No record'];else{q('INSERT INTO attendance(tenant_id,student_id,attendance_date,status) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status)',[$tid,$sid,$day,$value]);$result=['event_key'=>$event,'status'=>'applied'];}}
  elseif($kind==='score'){$a=lp_assessment($u,(int)($op['assessment_id']??0),true);q('SELECT id FROM classes WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$a['class_id']]);$s=q('SELECT * FROM students WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$sid])->fetch();if(!$s||(int)$s['class_id']!==(int)$a['class_id']||acPublished($tid,(int)$a['class_id'],$a['session_name'],$a['term_name']))throw new RuntimeException('Student scope changed or results are published.');$r=q('SELECT * FROM ac_scores WHERE tenant_id=? AND assessment_id=? AND student_id=? FOR UPDATE',[$tid,$a['id'],$sid])->fetch()?:null;$value=lp_num((string)($op['value']??''),(float)$a['max_score']);if(!hash_equals($base,at_score_hash($r))||($r&&$r['status']!=='draft'))$result=['event_key'=>$event,'status'=>'conflict','current'=>$r['score']??'No record'];else{q("INSERT INTO ac_scores(tenant_id,assessment_id,student_id,score,status,entered_by) VALUES(?,?,?,?,'draft',?) ON DUPLICATE KEY UPDATE score=VALUES(score),entered_by=VALUES(entered_by)",[$tid,$a['id'],$sid,$value,$u['id']]);$result=['event_key'=>$event,'status'=>'applied'];}}
  else throw new RuntimeException('Offline sync supports attendance and draft scores only.');q('INSERT INTO ix_sync(tenant_id,user_id,event_key,payload_hash,result_json) VALUES(?,?,?,?,?)',[$tid,$u['id'],$event,$hash,json_encode($result)]);audit('offline.'.$result['status'],$kind,$event);return $result;});}catch(Throwable $e){$results[]=['event_key'=>$event,'status'=>'denied','reason'=>$e->getMessage()];}}return $results;
}
function at_render(array $u):void{
 $tid=(int)$u['tenant_id'];$manager=ix_can($u,'curriculum_manager');$tabs=['cards'=>'Report cards'];if($u['role']==='teacher'||$manager)$tabs['observations']='Nursery observations';if($manager)$tabs+=['curricula'=>'NERDC / school curricula','designer'=>'Visual report designer','calendar'=>'State calendars & rules'];if(ix_can($u,'timetable_manager'))$tabs['timetable']='Smart timetable';if($u['role']==='teacher')$tabs['offline']='Offline workspace';$view=ix_tabs('academics',$tabs,'cards');op_card($tabs[$view]);
 if($view==='cards'){$sc=in_array($u['role'],['parent','student'],true)?sv_children($u):op_choices($u['role']==='teacher'&&!$manager?q('SELECT DISTINCT s.id,s.name FROM students s JOIN classes c ON c.id=s.class_id AND c.tenant_id=s.tenant_id JOIN ac_allocations a ON a.class_id=c.id AND a.tenant_id=c.tenant_id AND a.session_name=c.session_name WHERE s.tenant_id=? AND a.teacher_id=?',[$tid,$u['id']])->fetchAll():q('SELECT id,name FROM students WHERE tenant_id=?',[$tid])->fetchAll());echo '<form method="get" class="op-form"><input type="hidden" name="ix_report_card" value="1">';op_select('student_id','Student',$sc);op_select('design_id','Approved report format',op_choices(q("SELECT id,name FROM at_designs WHERE tenant_id=? AND status='approved'",[$tid])->fetchAll()));op_field('session_name','Session');op_field('term_name','Term');op_end('Open approved printable card');echo '<p>Primary/secondary cards require published, complete approved results whose CA/exam weights match the selected school-reviewed design. Nursery cards show approved observations. Grade thresholds and promotion-review conventions are configurable; promotion is never automatic.</p>';}
 elseif($view==='observations'){ix_form('at_observation',['student_id'=>['Assigned student ID','number'],'session_name'=>['Session','text'],'term_name'=>['Term','text'],'skill'=>['Observed developmental skill','text'],'rating'=>['Rating 1–5','number'],'note'=>['Observation / teacher comment','textarea']],'Submit observation');if($manager){op_table(q('SELECT id,student_id,skill,rating,note,status,created_by FROM at_observations WHERE tenant_id=? ORDER BY id DESC LIMIT 100',[$tid])->fetchAll(),['ID','Student','Skill','Rating','Comment','Status','Author']);ix_form('at_approve_observation',['record_id'=>['Draft observation ID','number']],'Approve as a different reviewer');}}
 elseif($view==='curricula'){op_table(q('SELECT id,name,authority,version,reference_url,subjects_json,status FROM at_curricula WHERE tenant_id=?',[$tid])->fetchAll(),['ID','Name','Authority','Version','Reference','School subject IDs','Status']);ix_form('at_subject',['name'=>['School subject name','text'],'code'=>['Subject code','text']],'Add school-specific subject');ix_form('at_curriculum',['name'=>['Curriculum label','text'],'authority'=>['Source',['NERDC'=>'NERDC reference','school'=>'School curriculum']],'version'=>['Version / effective revision','text'],'reference_url'=>['Source reference HTTPS URL','url'],'subjects'=>['Comma-separated existing school subject IDs','text']],'Create versioned curriculum draft');ix_form('at_approve_curriculum',['record_id'=>['Draft curriculum ID','number']],'Approve independently');ix_form('at_class_policy',['class_id'=>['Class ID','number'],'curriculum_id'=>['Approved curriculum ID','number'],'design_id'=>['Approved report format ID','number'],'calendar_id'=>['School calendar ID','number']],'Bind class policy');}
 elseif($view==='designer'){
  echo '<p>Drag blocks or use Move up/down on Android. The saved format contains only approved block names, not arbitrary HTML or executable code.</p><ol id="atBlocks">';foreach(['identity','subjects','attendance','skills','teacher_comment','head_comment','promotion','signatures'] as $b)echo '<li draggable="true" data-block="'.$b.'"><label><input type="checkbox" checked> '.e(str_replace('_',' ',$b)).'</label> <button type="button" data-up>↑</button> <button type="button" data-down>↓</button></li>';echo '</ol>';ix_form('at_design',['name'=>['Design name','text'],'level'=>['Level',['nursery'=>'Nursery','primary'=>'Primary','secondary'=>'Secondary']],'layout'=>['Ordered block JSON','textarea','["identity","subjects","attendance","skills","teacher_comment","head_comment","promotion","signatures"]'],'ca_weight'=>['CA weight','number','40'],'exam_weight'=>['Exam weight','number','60'],'promotion_percent'=>['Promotion review threshold','number','50'],'grades'=>['Descending grade-band JSON','textarea','[{"minimum":80,"grade":"A"},{"minimum":70,"grade":"B"},{"minimum":60,"grade":"C"},{"minimum":50,"grade":"D"},{"minimum":0,"grade":"Needs support"}]']],'Save immutable design draft');echo '<script>(()=>{const l=document.getElementById("atBlocks"),f=document.querySelector("textarea[name=layout]");let drag;const save=()=>f.value=JSON.stringify([...l.children].filter(x=>x.querySelector("input").checked).map(x=>x.dataset.block));l.onchange=save;l.onclick=e=>{const li=e.target.closest("li");if(!li)return;if(e.target.hasAttribute("data-up")&&li.previousElementSibling)l.insertBefore(li,li.previousElementSibling);if(e.target.hasAttribute("data-down")&&li.nextElementSibling)l.insertBefore(li.nextElementSibling,li);save()};l.ondragstart=e=>{drag=e.target.closest("li")};l.ondragover=e=>e.preventDefault();l.ondrop=e=>{e.preventDefault();const target=e.target.closest("li");if(drag&&target&&drag!==target)l.insertBefore(drag,target);save()}})();</script>';op_table(q('SELECT id,name,level,layout_json,ca_weight,exam_weight,status FROM at_designs WHERE tenant_id=?',[$tid])->fetchAll(),['ID','Name','Level','Blocks','CA','Exam','Status']);ix_form('at_approve_design',['record_id'=>['Draft design ID','number']],'Approve as a different reviewer');
 }elseif($view==='calendar'){op_table(q('SELECT id,name,state_name,year_name,starts_on,ends_on,holidays_json,inspection_notes FROM at_calendars WHERE tenant_id=?',[$tid])->fetchAll(),['ID','Name','State','Year','From','To','Holiday dates','Inspection rules']);ix_form('at_calendar',['name'=>['Calendar name','text'],'state_name'=>['State / FCT',array_combine(at_states(),at_states())],'year_name'=>['School academic year','text'],'starts_on'=>['Starts','date'],'ends_on'=>['Ends','date'],'holidays'=>['Approved holiday dates JSON','textarea','[]'],'inspection_notes'=>['Applicable inspection / school rules with responsible reviewer','textarea'],'reference_url'=>['Official / school-approved source HTTPS URL','url']],'Save reviewed state calendar');}
 elseif($view==='offline'){echo '<p>Capture only assigned-class attendance and draft assessment scores. A trusted device and a passphrase encrypt the local roster and queue. School approval, HTTPS and browser storage/WebCrypto support are required. Sync rechecks the current account, allocation, base version and publication state; conflicts remain for human reconciliation.</p><a class="btn" href="public/offline/offline_teacher.html">Open encrypted teacher workspace</a><p>Offline data is selective, not a cached copy of Finance or the full application. Keep the passphrase safe, sync before switching devices, and use Delete local workspace on shared devices.</p>';}
 else{op_table(q('SELECT id,name,capacity FROM at_rooms WHERE tenant_id=?',[$tid])->fetchAll(),['Room ID','Name','Capacity']);op_table(q('SELECT id,weekday,start_time,end_time FROM at_slots WHERE tenant_id=? ORDER BY weekday,start_time',[$tid])->fetchAll(),['Slot','Weekday 1–7','Start','End']);ix_form('at_room',['name'=>['Room name','text'],'capacity'=>['Room capacity','number']],'Register room');ix_form('at_slot',['weekday'=>['Weekday 1 Monday–7 Sunday','number'],'start_time'=>['Starts','time'],'end_time'=>['Ends','time']],'Add allowed teaching slot');ix_form('at_unavailable',['user_id'=>['Teacher account ID','number'],'weekday'=>['Weekday 1–7','number'],'start_time'=>['Unavailable from','time'],'end_time'=>['Unavailable to','time'],'reason'=>['Reason','text']],'Add teacher unavailability');ix_form('at_generate',['session_name'=>['School session','text'],'requirements'=>['Additional periods JSON: [{"allocation_id":1,"periods":2}]','textarea']],'Generate constraint-checked proposal');op_table(q('SELECT id,session_name,rows_json,status,created_by,approved_by,review_note FROM at_plans WHERE tenant_id=? ORDER BY id DESC LIMIT 30',[$tid])->fetchAll(),['Plan','Session','Proposed periods','Status','Author','Approver','Review']);ix_form('at_review_plan',['plan_id'=>['Draft proposal ID','number'],'review_note'=>['Review constraints and placement','textarea']],'Approve independently');if($u['role']==='school_admin')ix_form('at_apply_plan',['plan_id'=>['Approved proposal ID','number']],'Apply exact proposal once');echo '<p>A bounded heuristic/backtracking search balances repeated daily classes/subjects while checking teacher, class, room, capacity and availability conflicts. It adds requested periods; it never silently replaces the live timetable and does not claim global mathematical optimality. Changed inputs require regeneration.</p>';}
 echo '</section>';
